mapper.select:


FROM products p FORCE INDEX (idx_products_shop_status_id)
STRAIGHT_JOIN shops s ON s.id = p.shop_id AND s.enabled = 1
STRAIGHT_JOIN visible_categories c ON c.id = p.category_id


AND p.shop_id = #{shopId}
AND (#{afterId} IS NULL OR p.id < #{afterId})
ORDER BY p.id DESC LIMIT #{limit}
